import{_ as o,o as r,c as n,a2 as s}from"./chunks/framework.DGvnA5EY.js";const a="/workbuddy-guide/assets/01-official-sidebar.si-lsnLi.png",d="/workbuddy-guide/assets/02-menu-tidy-up.FASiO4aR.png",c=JSON.parse('{"title":"第 3 章 主界面、任务与工作区","description":"> 内容来源：WorkBuddy 官方指南 · 左侧导航栏（非官方整理，© 本指南作者，保留所有权利） 很多新手打开 WorkBuddy 第一眼会懵：左边一条竖排图标，点哪个都不知道干嘛。 这一章带你把最左边那条导航栏彻底搞清楚。它是你所有操作的\\"总入口\\"， 搞懂它，后面 90% 的功能你都能自己找到。","frontmatter":{"title":"第 3 章 主界面、任务与工作区"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 3 章 主界面、任务与工作区/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 3 章 主界面、任务与工作区/index.md","lastUpdated":1791615980000}'),e={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 3 章 主界面、任务与工作区/index.md"};function l(i,t,g,u,p,h){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="第-3-章-workbuddy-的主界面、任务与工作区" tabindex="-1">第 3 章 WorkBuddy 的主界面、任务与工作区 <a class="header-anchor" href="#第-3-章-workbuddy-的主界面、任务与工作区" aria-label="Permalink to &quot;第 3 章 WorkBuddy 的主界面、任务与工作区&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 左侧导航栏（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>很多新手打开 WorkBuddy 第一眼会懵：左边一条竖排图标，点哪个都不知道干嘛。 这一章带你把<strong>最左边那条导航栏</strong>彻底搞清楚。它是你所有操作的&quot;总入口&quot;， 搞懂它，后面 90% 的功能你都能自己找到。</p><h2 id="一、先看懂-导航栏长什么样" tabindex="-1">一、先看懂：导航栏长什么样 <a class="header-anchor" href="#一、先看懂-导航栏长什么样" aria-label="Permalink to &quot;一、先看懂：导航栏长什么样&quot;">​</a></h2><p>导航栏从上到下分成 4 块，记住这个顺序就够了：</p><table tabindex="0"><thead><tr><th>区域</th><th>里面有什么</th><th>白话解释</th></tr></thead><tbody><tr><td>顶部</td><td>版本号、「发现应用」</td><td>看当前版本，顺手发现新应用</td></tr><tr><td>一级入口</td><td>新建任务、助理、项目、专家·技能·连接器、自动化、资料库、更多</td><td>主力功能，点这里进对应页面</td></tr><tr><td>任务与空间</td><td>任务、空间</td><td>你做过的历史任务、工作区列表</td></tr><tr><td>底部</td><td>消息中心、多端协同、账号头像</td><td>消息、设备、账号设置</td></tr></tbody></table><p><strong>为什么先讲这个？</strong> 因为后面每章教的功能（比如&quot;怎么用技能&quot;&quot;怎么连连接器&quot;）， 第一步永远都是&quot;在左边导航栏点 XXX&quot;。你先把入口认熟，后面不用回头找。</p><p><img src="'+a+'" alt="官方界面里左侧导航栏的位置，标注了新建任务、助理、项目等入口" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="二、一级入口逐个认-这是你每天都会用的" tabindex="-1">二、一级入口逐个认（这是你每天都会用的） <a class="header-anchor" href="#二、一级入口逐个认-这是你每天都会用的" aria-label="Permalink to &quot;二、一级入口逐个认（这是你每天都会用的）&quot;">​</a></h2><ul><li><strong>新建任务</strong>：开启一个本地 AI 工作台，绝大多数活从这里开始。</li><li><strong>助理</strong>：云端助理，可以远程接任务、给你推消息（不在电脑前也能干活）。</li><li><strong>项目</strong>：按项目把任务归类，支持团队协作。</li><li><strong>专家·技能·连接器</strong>：这是&quot;能力中心&quot;——调专家、装技能、连外部服务，后面案例篇重点讲。</li><li><strong>自动化</strong>：设定时任务，让 WorkBuddy 按计划自己跑（比如每周一发周报）。</li><li><strong>资料库</strong>：文档、表格、网页等资料的统一收纳处。</li><li><strong>更多</strong>：低频入口的&quot;收纳盒&quot;——我的邮箱、腾讯文档、ima、乐享知识库、灵感、Genie BaaS。</li></ul><blockquote><p>小提示：入口多了以后，常用的留外面，不常用的收进「更多」，每天少点好几下。</p></blockquote><h2 id="三、动手做-把导航栏调成你顺手的样子" tabindex="-1">三、动手做：把导航栏调成你顺手的样子 <a class="header-anchor" href="#三、动手做-把导航栏调成你顺手的样子" aria-label="Permalink to &quot;三、动手做：把导航栏调成你顺手的样子&quot;">​</a></h2><p>官方允许你自己排菜单顺序。跟着做一遍：</p><ol><li>在左侧导航栏<strong>任意位置点右键</strong>。</li><li>在右键菜单里点 <strong>「自定义菜单」</strong>，会弹出自定义面板。</li><li>面板里有「一级菜单」和「更多」两组： <ul><li><strong>组内排序</strong>：按住条目右边的手柄上下拖，改同一组里的先后。</li><li><strong>跨组移动</strong>：把条目拖到另一组，就能在&quot;一级菜单&quot;和&quot;更多&quot;之间切换。</li></ul></li><li><strong>「新建任务」是固定项</strong>，不能拖，也不能收进「更多」（它是你的主入口，得一直在）。</li><li>拖完<strong>不用点保存</strong>，面板和导航栏同时可见，即时生效；关掉面板配置也会留着，重开客户端还是你排的顺序。</li></ol><p><img src="'+d+'" alt="从太乱到提到外层再到收进更多，最后顺手好找" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解整理菜单的思路，与实际软件界面无关。</em></p><p><strong>做完的样子</strong>：你把&quot;新建任务、助理、项目&quot;放一级，剩下的塞进「更多」， 下次打开 WorkBuddy，最常用的三个一眼就能点到。</p><h2 id="四、一个坑-自定义只存在这台电脑上" tabindex="-1">四、一个坑：自定义只存在这台电脑上 <a class="header-anchor" href="#四、一个坑-自定义只存在这台电脑上" aria-label="Permalink to &quot;四、一个坑：自定义只存在这台电脑上&quot;">​</a></h2><p>你调好的顺序<strong>只保存在当前设备</strong>，目前不跨设备同步。 换一台电脑登录，导航栏会按那台电脑自己的设置显示——不是你之前调的。</p><p><strong>应对</strong>：公司/家里两台电脑都用的话，各自调一次；或者把常用功能都放一级菜单， 减少依赖顺序。</p><h2 id="五、本章任务清单-做完就算过关" tabindex="-1">五、本章任务清单（做完就算过关） <a class="header-anchor" href="#五、本章任务清单-做完就算过关" aria-label="Permalink to &quot;五、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 能说出导航栏 4 块分别是什么</li><li>[ ] 打开「自定义菜单」，把 3 个常用功能拖到一级</li><li>[ ] 确认「新建任务」无法被收进「更多」</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章出现了几个容易卡住的词，这里补一句人话解释，看不懂可以跳过正文直接看这里。</p></blockquote><p><strong>导航栏 / 侧边栏</strong> 界面<strong>最左边那条竖着的菜单栏</strong>。软件的所有功能入口都在这里， 点某个图标就进对应页面。文中&quot;导航栏&quot;和&quot;侧边栏&quot;说的是同一个东西。</p><p><strong>一级菜单 / 一级入口</strong> 菜单的<strong>最外层</strong>，直接能点到的那些项。往里还有「更多」这种收纳项， 要点进去才能看到里面的东西。把常用的放一级，是为了少点一次。</p><p><strong>「更多」</strong> 一个<strong>收纳盒</strong>。低频、不常用的功能会被收在这里，避免主菜单塞太满。 点开它才能看到里面的条目。</p><p><strong>自定义菜单</strong> 官方提供的<strong>调整菜单顺序和分组</strong>的功能。改完即时生效，不用保存按钮， 关掉面板设置也留着。</p><p><strong>跨组移动</strong> 把一个菜单项从「一级菜单」<strong>拖到「更多」</strong>，或者反过来。 拖完之后它就在不同的层级上了。</p><p><strong>固定项</strong> 指<strong>不能被移动或隐藏的菜单项</strong>。这一版里只有「新建任务」是固定项—— 它是主入口，必须一直在。</p><p><strong>消息中心</strong> 放系统通知和消息的地方，比如任务完成了、更新了之类的提醒。</p><p><strong>多端协同</strong> 指<strong>多个设备一起用</strong>。比如电脑上开的任务，手机端也能接。</p><p><strong>跨设备同步</strong> 指<strong>在 A 电脑做的设置，B 电脑上自动也有</strong>。这一版的自定义菜单<strong>不支持</strong>跨设备同步， 所以两台电脑要分别设置。</p><p><strong>工作空间（Workspace）</strong> 一个<strong>工作目录</strong>。导航栏里的「空间」就是它的入口——把相关任务归到一个空间里， 方便集中管理。第 4 章会讲怎么在任务里选工作空间。</p><hr><p><em>下一篇：第 4 章 快速完成第一个 WorkBuddy 任务——用刚才认识的「新建任务」真做一件事。</em></p>',38)])])}const b=o(e,[["render",l]]);export{c as __pageData,b as default};
